import Dispatch
final class ShoeCatalog {
    private let queue = DispatchQueue(label: "shoe.catalog")
    private var sizes = [38, 39]
    func largest() -> Int { queue.sync { sizes.max() ?? 0 } }
    func addNext() {
        queue.sync {
            let next = (sizes.max() ?? 0) + 1
            sizes.append(next)
        }
    }
}
let catalog = ShoeCatalog()
catalog.addNext()
print(catalog.largest())

Вывод 40. Исходник ждал собственную очередь через вызов публичного метода — цикл не виден по одной строке sync, его выдаёт только граф вызовов. Внутри блока очередь уже владеет sizes, поэтому повторная постановка не нужна.

